  Background,
  Controls,
  MiniMap,
  Handle,
  Position,
} from "reactflow";

import "reactflow/dist/style.css";

import {
  workers,
  partitions,
  topologyStatus,
} from "../data/mockData";


/* =========================================================
   KAFKA NODE
   ========================================================= */

function KafkaTopologyNode({ data }) {
  return (
    <div className="detailed-topology-node">

      <Handle
        type="source"
        position={Position.Right}
      />

      <div className="detailed-node-header">

        <strong>
          Kafka
        </strong>

        <span className="topology-health-dot">
          ●
        </span>

      </div>

      <div className="detailed-node-main-value">
        {data.partitionCount}
      </div>

      <div className="detailed-node-label">
        Active Partitions
      </div>

      <div className="detailed-node-info">
        Topic: truck-telemetry
      </div>

    </div>
  );
}


/* =========================================================
   PROCESSOR NODE
   ========================================================= */

function ProcessorTopologyNode({ data }) {
  return (
    <div className="detailed-topology-node processor-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <Handle
        type="source"
        position={Position.Right}
      />

      <div className="detailed-node-header">

        <strong>
          Stream Processor
        </strong>

        <span className="topology-health-dot">
          ●
        </span>

      </div>

      <div className="processor-name">
        Bytewax / Faust
      </div>

      <div className="detailed-node-info">
        Consume → Filter → Map → Window
      </div>

      <div className="detailed-node-info">
        {data.workerCount} workers
      </div>

    </div>
  );
}


/* =========================================================
   OUTPUT NODE
   ========================================================= */

function OutputTopologyNode({ data }) {
  return (
    <div className="detailed-topology-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <Handle
        type="source"
        position={Position.Right}
      />

      <div className="detailed-node-header">

        <strong>
          Temperature Aggregation
        </strong>

        <span className="topology-health-dot">
          ●
        </span>

      </div>

      <div className="detailed-node-label">
        5-minute rolling average
      </div>

      <div className="detailed-node-info">
        Per-truck aggregation
      </div>

    </div>
  );
}


/* =========================================================
   ROCKSDB NODE
   ========================================================= */

function RocksTopologyNode({ data }) {
  return (
    <div className="detailed-topology-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <div className="detailed-node-header">

        <strong>
          RocksDB
        </strong>

        <span className="topology-health-dot">
          ●
        </span>

      </div>

      <div className="detailed-node-label">
        State Store
      </div>

      <div className="detailed-node-info">
        {data.status}
      </div>

    </div>
  );
}


/* =========================================================
   PROMETHEUS NODE
   ========================================================= */

function PrometheusTopologyNode({ data }) {
  return (
    <div className="detailed-topology-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <Handle
        type="source"
        position={Position.Right}
      />

      <div className="detailed-node-header">

        <strong>
          Prometheus
        </strong>

        <span className="topology-health-dot">
          ●
        </span>

      </div>

      <div className="detailed-node-label">
        Metrics
      </div>

      <div className="detailed-node-info">
        Worker performance
      </div>

    </div>
  );
}


/* =========================================================
   MONITORING NODE
   ========================================================= */

function MonitoringTopologyNode() {
  return (
    <div className="detailed-topology-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <div className="detailed-node-header">

        <strong>
          StreamForge UI
        </strong>

        <span className="topology-health-dot">
          ●
        </span>

      </div>

      <div className="detailed-node-label">
        Topology Monitor
      </div>

      <div className="detailed-node-info">
        React Flow Dashboard
      </div>

    </div>
  );
}


/* =========================================================
   NODE TYPES
   ========================================================= */

const nodeTypes = {
  kafkaDetailed: KafkaTopologyNode,
  processorDetailed: ProcessorTopologyNode,
  outputDetailed: OutputTopologyNode,
  rocksDetailed: RocksTopologyNode,
  prometheusDetailed: PrometheusTopologyNode,
  monitoringDetailed: MonitoringTopologyNode,
};


/* =========================================================
   MAIN COMPONENT
   ========================================================= */

function Topology() {

  const [showMinimap, setShowMinimap] = useState(true);


  const healthyWorkers = workers.filter(
    (worker) => worker.status === "healthy"
  ).length;


  const failedWorkers = workers.filter(
    (worker) => worker.status === "failed"
  ).length;


  const nodes = useMemo(
    () => [

      {
        id: "kafka",

        type: "kafkaDetailed",

        position: {
          x: 50,
          y: 230,
        },

        data: {
          partitionCount: partitions.length,
        },
      },


      {
        id: "processor",

        type: "processorDetailed",

        position: {
          x: 330,
          y: 230,
        },

        data: {
          workerCount: workers.length,
        },
      },


      {
        id: "output",

        type: "outputDetailed",

        position: {
          x: 650,
          y: 230,
        },

        data: {},
      },


      {
        id: "rocksdb",

        type: "rocksDetailed",

        position: {
          x: 650,
          y: 80,
        },

        data: {
          status:
            topologyStatus.rocksdb.status,
        },
      },


      {
        id: "prometheus",

        type: "prometheusDetailed",

        position: {
          x: 650,
          y: 390,
        },

        data: {},
      },


      {
        id: "monitoring",

        type: "monitoringDetailed",

        position: {
          x: 960,
          y: 390,
        },

        data: {},
      },

    ],
    []
  );


  const edges = useMemo(
    () => [

      {
        id: "kafka-processor",

        source: "kafka",
        target: "processor",

        animated: true,
      },


      {
        id: "processor-output",

        source: "processor",
        target: "output",

        animated: true,
      },


      {
        id: "processor-rocks",

        source: "processor",
        target: "rocksdb",

        animated: true,

        style: {
          strokeDasharray: "5 5",
        },
      },


      {
        id: "processor-prometheus",

        source: "processor",
        target: "prometheus",

        animated: true,

        style: {
          strokeDasharray: "5 5",
        },
      },


      {
        id: "prometheus-monitoring",

        source: "prometheus",
        target: "monitoring",

        animated: true,

        style: {
          strokeDasharray: "5 5",
        },
      },

    ],
    []
  );


  return (

    <div className="topology-page">

      {/* ==================================================
          Header
      ================================================== */}

      <div className="topology-page-header">

        <div>

          <h1>
            Stream Topology
          </h1>

          <p>
            Detailed view of the StreamForge distributed processing pipeline
          </p>

        </div>


        <div className="topology-page-status">

          <span className="status-dot"></span>

          System Operational

        </div>

      </div>


      {/* ==================================================
          Summary
      ================================================== */}

      <div className="topology-summary">

        <div className="topology-summary-item">

          <span>
            Workers
          </span>

          <strong>
            {workers.length}
          </strong>

          <small>
            {healthyWorkers} healthy
          </small>

        </div>


        <div className="topology-summary-item">

          <span>
            Partitions
          </span>

          <strong>
            {partitions.length}
          </strong>

          <small>
            Active Kafka partitions
          </small>

        </div>


        <div className="topology-summary-item">

          <span>
            Processor
          </span>

          <strong>
            Online
          </strong>

          <small>
            Bytewax / Faust
          </small>

        </div>


        <div className="topology-summary-item">

          <span>
            Worker Failures
          </span>

          <strong
            className={
              failedWorkers > 0
                ? "failure-value"
                : ""
            }
          >
            {failedWorkers}
          </strong>

          <small>
            Current failures
          </small>

        </div>

      </div>


      {/* ==================================================
          Graph controls
      ================================================== */}

      <div className="topology-toolbar">

        <div>

          <strong>
            Processing Pipeline
          </strong>

          <span>
            Live architecture view
          </span>

        </div>


        <div className="topology-toolbar-actions">

          <button
            className="topology-toolbar-button"
            onClick={() =>
              setShowMinimap(!showMinimap)
            }
          >
            {showMinimap
              ? "Hide Minimap"
              : "Show Minimap"}
          </button>

        </div>

      </div>


      {/* ==================================================
          Graph
      ================================================== */}

      <div className="detailed-topology-container">

        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={nodeTypes}

          fitView

          fitViewOptions={{
            padding: 0.25,
          }}

          nodesDraggable={true}
          nodesConnectable={false}
        >

          <Background
            gap={20}
            size={1}
          />

          <Controls />

          {showMinimap && (
            <MiniMap />
          )}

        </ReactFlow>

      </div>


      {/* ==================================================
          Legend
      ================================================== */}

      <div className="topology-legend">

        <div className="legend-title">
          Connection Types
        </div>


        <div className="legend-item">

          <span className="legend-line"></span>

          Data Flow

        </div>


        <div className="legend-item">

          <span className="legend-dashed-line"></span>

          Monitoring / State

        </div>

      </div>

    </div>

  );
}


export default Topology;
